def _fc(fid, cat, front, back, detail):
    return {'id': fid, 'cat': cat, 'front': front, 'back': back, 'detail': detail}


def _mc(qid, cat, question, options, correct, explanation, why=None):
    q = {'id': qid, 'cat': cat, 'type': 'mc', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _ms(qid, cat, question, options, correct, explanation, why=None):
    q = {'id': qid, 'cat': cat, 'type': 'ms', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _tf(qid, cat, question, answer, explanation, why=None):
    q = {'id': qid, 'cat': cat, 'type': 'tf', 'question': question, 'answer': answer, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


