# Present answer options in a stable, spread-out order (the app also shuffles at render time),
# so the correct option does not always sit in the same source position.
import random as _random


def _spread_options(q):
    if q.get('type') not in ('mc', 'ms'):
        return
    opts = q['options']
    order = list(range(len(opts)))
    _random.Random(q.get('id', '')).shuffle(order)
    q['options'] = [opts[i] for i in order]
    if q['type'] == 'mc':
        q['correct'] = order.index(q['correct'])
    else:
        q['correct'] = sorted(order.index(c) for c in q['correct'])


for _q in QUESTIONS:
    _spread_options(_q)
for _cs in CASE_STUDIES:
    for _q in _cs['questions']:
        _spread_options(_q)
